"use client";

import DashboardLayout from "@/components/layout/dashboard-layout";
import {
  getSalesAnalytics,
  getProductAnalytics,
  getSupplierAnalytics,
  getDashboardAnalytics,
  getProfitabilityAnalytics
} from "@/services/analytics";

import { useQuery } from "@tanstack/react-query";
import RoleGuard from "@/components/auth/RoleGuard";
import MetricCard from "@/components/analytics/metric-card";
import CategoryDistribution from "@/components/analytics/category-distribution";
import ProfitabilityChart from "@/components/analytics/profitability-chart";
import TopCustomers from "@/components/analytics/top-customers";
import { 
  DollarSign, 
  Package, 
  TrendingUp, 
  AlertTriangle,
  ShoppingBag,
  Users
} from "lucide-react";
import { motion } from "framer-motion";

export default function AnalyticsPage() {
  const stats = useQuery({
    queryKey: ["dashboard-stats"],
    queryFn: getDashboardAnalytics
  });

  const sales = useQuery({
    queryKey: ["sales-analytics"],
    queryFn: getSalesAnalytics
  });

  const products = useQuery({
    queryKey: ["product-analytics"],
    queryFn: getProductAnalytics
  });

  const profitability = useQuery({
    queryKey: ["profitability-analytics"],
    queryFn: getProfitabilityAnalytics
  });

  const suppliers = useQuery({
    queryKey: ["supplier-analytics"],
    queryFn: getSupplierAnalytics
  });

  const isLoading = stats.isLoading || sales.isLoading || products.isLoading || profitability.isLoading;

  if (isLoading) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center h-[60vh]">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-500"></div>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <RoleGuard allowedRoles={["ADMIN"]}>
      <DashboardLayout>
        <div className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">
              Analytics Overview
            </h1>
            <p className="text-slate-500 mt-1">
              Real-time insights into your business performance.
            </p>
          </div>
          <div className="flex gap-2">
            <button className="px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors">
              Last 30 Days
            </button>
            <button className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors">
              Export Report
            </button>
          </div>
        </div>

        {/* KPI Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <MetricCard
            title="Total Revenue"
            value={`$${stats.data?.revenue?.toLocaleString() || 0}`}
            icon={<DollarSign size={20} />}
            trend={{ value: 12.5, isPositive: true }}
            description="Across all completed sales"
          />
          <MetricCard
            title="Inventory Value"
            value={`$${stats.data?.inventoryValue?.toLocaleString() || 0}`}
            icon={<Package size={20} />}
            description="Total value of stock on hand"
          />
          <MetricCard
            title="Avg Order Value"
            value={`$${sales.data?.averageOrderValue?.toFixed(2) || 0}`}
            icon={<TrendingUp size={20} />}
            trend={{ value: 4.2, isPositive: true }}
            description="Revenue per sale"
          />
          <MetricCard
            title="Low Stock Alert"
            value={stats.data?.lowStockCount || 0}
            icon={<AlertTriangle size={20} className={stats.data?.lowStockCount > 0 ? "text-rose-500" : ""} />}
            description="Items below threshold"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
          {/* Main Profitability Chart */}
          <div className="lg:col-span-2">
            <ProfitabilityChart data={profitability.data || []} />
          </div>

          {/* Top Customers */}
          <div className="lg:col-span-1">
            <TopCustomers customers={sales.data?.topCustomers || []} />
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Category Distribution */}
          <div className="lg:col-span-1">
            <CategoryDistribution data={products.data?.categoryDistribution || []} />
          </div>

          {/* Top Products Table */}
          <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-lg font-semibold text-slate-800 tracking-tight">
                Product Performance
              </h2>
              <ShoppingBag size={20} className="text-slate-400" />
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="text-xs font-semibold text-slate-400 uppercase tracking-wider border-b border-slate-100">
                    <th className="pb-4">Product Name</th>
                    <th className="pb-4">Units Sold</th>
                    <th className="pb-4">Total Revenue</th>
                    <th className="pb-4">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {products.data?.topSellingProducts?.map((p: any) => (
                    <tr key={p.id} className="group hover:bg-slate-50/50 transition-colors">
                      <td className="py-4 font-medium text-slate-900">{p.name}</td>
                      <td className="py-4 text-slate-600">{p.sales}</td>
                      <td className="py-4 text-slate-600 font-medium">${(p.sales * p.price).toLocaleString()}</td>
                      <td className="py-4">
                        <span className="px-2 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-bold rounded-md uppercase">
                          High Demand
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        {/* Supplier Performance Section */}
        <div className="mt-12 bg-slate-900 text-white p-8 rounded-3xl overflow-hidden relative">
          <div className="absolute top-0 right-0 p-8 opacity-10">
            <Users size={200} />
          </div>
          <div className="relative z-10">
            <h2 className="text-2xl font-bold mb-2">Supplier Reliability</h2>
            <p className="text-slate-400 mb-8 max-w-lg">
              Overview of procurement channels and supplier fulfillment metrics.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {suppliers.data?.supplierPerformance?.slice(0, 4).map((s: any) => (
                <div key={s.id} className="bg-white/5 backdrop-blur-sm p-4 rounded-xl border border-white/10 hover:bg-white/10 transition-colors">
                  <p className="text-xs text-slate-400 uppercase tracking-widest">{s.name}</p>
                  <p className="text-xl font-bold mt-1">{s.orders} Orders</p>
                  <p className="text-sm text-emerald-400 mt-2">${s.totalSpent.toLocaleString()} spent</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </DashboardLayout>
    </RoleGuard>
  );
}